import{_ as e,r as a,o,c,e as n,a as l,s as u}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"文件附件 - October CMS - 3.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"创建新附件","slug":"创建新附件","link":"#创建新附件","children":[{"level":3,"title":"处理多个附件","slug":"处理多个附件","link":"#处理多个附件","children":[]}]},{"level":2,"title":"查看附件","slug":"查看附件","link":"#查看附件","children":[{"level":3,"title":"访问本地路径","slug":"访问本地路径","link":"#访问本地路径","children":[]}]},{"level":2,"title":"调整缩略图大小","slug":"调整缩略图大小","link":"#调整缩略图大小","children":[]},{"level":2,"title":"输出和下载","slug":"输出和下载","link":"#输出和下载","children":[]},{"level":2,"title":"用法示例","slug":"用法示例","link":"#用法示例","children":[]},{"level":2,"title":"验证示例","slug":"验证示例","link":"#验证示例","children":[]}],"relativePath":"3.x/zh-cn/extend/database/attachments.md","filePath":"3.x/zh-cn/extend/database/attachments.md"}'),i={name:"3.x/zh-cn/extend/database/attachments.md"};function r(k,s,d,g,m,h){const t=a("pre-heading"),p=a("post-heading");return o(),c("div",null,[n(t),s[0]||(s[0]=l("h1",null,"文件附件",-1)),n(p),s[1]||(s[1]=u(`<p>模型可以使用<a href="./relations.html">多态关联</a>的子集来支持文件附件。<code>$attachOne</code> 或 <code>$attachMany</code> 关联专为将文件链接到称为&quot;附件&quot;的数据库记录而设计。在几乎所有情况下，<code>System\\Models\\File</code> 模型用于维护此关联，其中对文件的引用作为记录存储在 <code>system_files</code> 表中，并与父模型有多态关联。</p><p>在以下示例中，模型有一个 Avatar 附件模型和多个 Photo 附件模型。</p><p>单个文件附件：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token variable">$attachOne</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;avatar&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>System<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>File</span><span class="token operator">::</span><span class="token keyword">class</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><p>多个文件附件：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token variable">$attachMany</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;photos&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>System<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>File</span><span class="token operator">::</span><span class="token keyword">class</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block warning"><p>为避免命名冲突，请确保您模型的数据库表没有已经使用与附件关联相同名称的属性。</p></div><p>受保护的附件上传到应用程序的 <strong>uploads/protected</strong> 目录，该目录无法从 Web 直接访问。通过将 <code>public</code> 属性设置为 <code>false</code> 来定义受保护的文件附件。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token variable">$attachOne</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;avatar&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>System<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>File</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;public&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">false</span><span class="token punctuation">]</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="创建新附件"><a href="#创建新附件" class="header-anchor">#</a> 创建新附件</h2><p>对于单数附加关联（<code>$attachOne</code>），您可以通过模型关联直接创建附件，使用 <code>files</code> 函数设置其值，该函数从输入上传读取文件数据。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">avatar</span> <span class="token operator">=</span> <span class="token function">files</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;file_input&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>要从本地路径关联新文件，请使用 <code>System\\Models\\File</code> 模型和 <code>fromFile</code> 方法。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">avatar</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">File</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">fromFile</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;/path/to/somefile.jpg&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>要直接从（原始）数据创建文件，请使用 <code>fromData</code> 方法传递内容（第一个参数）和文件名（第二个参数）。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">avatar</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">File</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">fromData</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Some content&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;sometext.txt&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>您还可以使用 <code>fromUrl</code> 方法从 URL 添加文件。要使用此方法，您需要安装 cURL PHP 扩展。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">avatar</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">File</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">fromUrl</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;https://example.tld/path/to/avatar.jpg&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>可选地，您可以指定自定义文件名（第二个参数）。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">avatar</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">File</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">fromUrl</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;https://example.tld/avatar.jpg&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;customname.jpg&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="处理多个附件"><a href="#处理多个附件" class="header-anchor">#</a> 处理多个附件</h3><p>对于多数附加关联（<code>$attachMany</code>），您可以从 <code>files()</code> 函数传递一个值数组。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">photos</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token keyword type-casting">array</span><span class="token punctuation">)</span> <span class="token function">files</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;multi_file&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>您可以使用 <code>create</code> 方法在现有关联上追加文件，请注意文件对象关联到 <code>data</code> 属性。此方法也可用于单数关联，如果您愿意的话。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">photos</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">create</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;data&#39;</span> <span class="token operator">=&gt;</span> <span class="token function">files</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;file_input&#39;</span><span class="token punctuation">)</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>您可以在关联上使用 <code>add</code> 方法直接操作 <code>System\\Models\\File</code> 模型。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">photos</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">add</span><span class="token punctuation">(</span>
    <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">photos</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">fromFile</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;/path/to/somefile.jpg&#39;</span><span class="token punctuation">)</span>
<span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>或者，您可以预先准备一个 File 模型，然后手动关联关系。请注意，使用此方法时必须显式设置 <code>is_public</code> 属性。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$file</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>System<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>File</span><span class="token punctuation">;</span>
<span class="token variable">$file</span><span class="token operator">-&gt;</span><span class="token property">data</span> <span class="token operator">=</span> <span class="token function">files</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;file_input&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$file</span><span class="token operator">-&gt;</span><span class="token property">is_public</span> <span class="token operator">=</span> <span class="token constant boolean">true</span><span class="token punctuation">;</span>
<span class="token variable">$file</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">photos</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">add</span><span class="token punctuation">(</span><span class="token variable">$file</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="查看附件"><a href="#查看附件" class="header-anchor">#</a> 查看附件</h2><p><code>getUrl</code> 方法返回已上传公共文件的完整 URL。以下代码将打印类似 <strong>example.tld/uploads/public/path/to/avatar.jpg</strong> 的内容。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">echo</span> <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">avatar</span><span class="token operator">-&gt;</span><span class="token function">getUrl</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>返回多个附件文件路径。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">foreach</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">photos</span> <span class="token keyword">as</span> <span class="token variable">$photo</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">echo</span> <span class="token variable">$photo</span><span class="token operator">-&gt;</span><span class="token function">getUrl</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>使用 Twig 在页面上显示文件。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>img</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> model<span class="token punctuation">.</span>avatar<span class="token punctuation">.</span>url <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span> <span class="token attr-name">alt</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>Description Image<span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
</code></pre></div><h3 id="访问本地路径"><a href="#访问本地路径" class="header-anchor">#</a> 访问本地路径</h3><p><code>getLocalPath</code> 方法将返回本地文件系统中已上传文件的绝对路径。如果使用外部驱动程序（如 S3），此方法将下载内容到本地文件系统中的临时位置。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">echo</span> <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">avatar</span><span class="token operator">-&gt;</span><span class="token function">getLocalPath</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="调整缩略图大小"><a href="#调整缩略图大小" class="header-anchor">#</a> 调整缩略图大小</h2><p>您可以使用 <code>getThumbUrl</code> 方法调整图片大小。该方法接受 3 个参数 - 图片宽度、图片高度和选项参数。</p><p><strong>宽度</strong>和<strong>高度</strong>参数应指定为数字或 <strong>auto</strong> 关键字以实现自动比例缩放。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">echo</span> <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">avatar</span><span class="token operator">-&gt;</span><span class="token function">getThumbUrl</span><span class="token punctuation">(</span><span class="token number">100</span><span class="token punctuation">,</span> <span class="token number">100</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;mode&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;crop&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>使用 Twig 在页面上显示图片。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>img</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> model<span class="token punctuation">.</span>avatar<span class="token punctuation">.</span>thumbUrl<span class="token punctuation">(</span><span class="token number">100</span><span class="token punctuation">,</span> <span class="token number">100</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> mode<span class="token punctuation">:</span> <span class="token string"><span class="token punctuation">&#39;</span>exact<span class="token punctuation">&#39;</span></span><span class="token punctuation">,</span> quality<span class="token punctuation">:</span> <span class="token number">80</span><span class="token punctuation">,</span> extension<span class="token punctuation">:</span> <span class="token string"><span class="token punctuation">&#39;</span>webp<span class="token punctuation">&#39;</span></span> <span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span> <span class="token attr-name">alt</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>Description Image<span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
</code></pre></div><p>阅读<a href="./../services/resizer.html">图像调整器文章</a>了解有关 <code>getThumbUrl</code> 可用选项的更多信息。</p><h2 id="输出和下载"><a href="#输出和下载" class="header-anchor">#</a> 输出和下载</h2><p>要直接输出文件内容，请使用 <code>output</code> 方法，这将返回一个包含在浏览器中显示文件所需头部的<a href="./../services/response-view.html">响应对象</a>。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">avatar</span><span class="token operator">-&gt;</span><span class="token function">output</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>您可以通过链接 <code>send</code> 方法将内容输出到浏览器。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">avatar</span><span class="token operator">-&gt;</span><span class="token function">output</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">send</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>返回 <code>download</code> 方法以将文件作为响应下载。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">avatar</span><span class="token operator">-&gt;</span><span class="token function">download</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="用法示例"><a href="#用法示例" class="header-anchor">#</a> 用法示例</h2><p>本节展示了模型附件功能的完整用法示例 - 从在模型中定义关联到在页面上显示上传的图片。</p><p>在您的模型中定义与 <code>System\\Models\\File</code> 类的关联，例如：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Post</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$attachOne</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;featured_image&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>System<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>File</span><span class="token operator">::</span><span class="token keyword">class</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>构建一个用于上传文件的表单：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Form</span><span class="token operator">::</span><span class="token function">open</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;files&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">true</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>input</span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>example_file<span class="token punctuation">&quot;</span></span> <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>file<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>submit<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>Upload File<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>

<span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Form</span><span class="token operator">::</span><span class="token function">close</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><p>在服务器上处理上传的文件并将其附加到模型：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// Find the Blog Post model</span>
<span class="token variable">$post</span> <span class="token operator">=</span> <span class="token class-name static-context">Post</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Save the featured image of the Blog Post model</span>
<span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token class-name static-context">Input</span><span class="token operator">::</span><span class="token function">hasFile</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;example_file&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token property">featured_image</span> <span class="token operator">=</span> <span class="token class-name static-context">Input</span><span class="token operator">::</span><span class="token function">file</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;example_file&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>或者，您可以使用<a href="./relations.html">延迟绑定</a>来延迟关联。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// Find the Blog Post model</span>
<span class="token variable">$post</span> <span class="token operator">=</span> <span class="token class-name static-context">Post</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Look for the postback data &#39;example_file&#39; in the HTML form above</span>
<span class="token variable">$fileFromPost</span> <span class="token operator">=</span> <span class="token class-name static-context">Input</span><span class="token operator">::</span><span class="token function">file</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;example_file&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// If it exists, save it as the featured image with a deferred session key</span>
<span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$fileFromPost</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token function">featured_image</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">create</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;data&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$fileFromPost</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token variable">$sessionKey</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>在页面上显示上传的文件：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?php</span>
<span class="token comment">// Find the Blog Post model again</span>
<span class="token variable">$post</span> <span class="token operator">=</span> <span class="token class-name static-context">Post</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Look for the featured image address, otherwise use a default one</span>
<span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token property">featured_image</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$featuredImage</span> <span class="token operator">=</span> <span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token property">featured_image</span><span class="token operator">-&gt;</span><span class="token function">getUrl</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
<span class="token keyword">else</span> <span class="token punctuation">{</span>
    <span class="token variable">$featuredImage</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;http://placehold.it/220x300&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
<span class="token delimiter important">?&gt;</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>img</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$featuredImage</span> <span class="token delimiter important">?&gt;</span></span><span class="token punctuation">&quot;</span></span> <span class="token attr-name">alt</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>Featured Image<span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
</code></pre></div><p>如果您需要访问文件的所有者，可以使用 <code>File</code> 模型的 <code>attachment</code> 属性：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token variable">$morphTo</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;attachment&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token punctuation">]</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><p>示例：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span> <span class="token operator">=</span> <span class="token variable">$file</span><span class="token operator">-&gt;</span><span class="token property">attachment</span><span class="token punctuation">;</span>
</code></pre></div><p>有关更多信息，请阅读<a href="./relations.html#relation-polymorphic-relations">多态关联</a></p><h2 id="验证示例"><a href="#验证示例" class="header-anchor">#</a> 验证示例</h2><p>以下示例使用<a href="./../services/validation.html">数组验证</a>来验证 <code>$attachMany</code> 关联。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">use</span> <span class="token package">System<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>File</span><span class="token punctuation">;</span>
<span class="token keyword">use</span> <span class="token package">Model</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">Gallery</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>Validation</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$attachMany</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;photos&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name static-context">File</span><span class="token operator">::</span><span class="token keyword">class</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$rules</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;photos&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;required&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;photos.*&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;image&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;max:1000&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;dimensions:min_width=100,min_height=100&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>有关上面使用的 <code>attribute.*</code> 语法的更多信息，请参阅<a href="./../services/validation.html">验证文章</a>中关于验证数组的部分。</p>`,74))])}const b=e(i,[["render",r]]);export{f as __pageData,b as default};
